contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        bool repayDirect_
    ) public {
        require(amount_ > 0, "amount must be positive");
        require(loanToCollateral_ > 0, "loanToCollateral must be positive");
        require(duration_ > 0, "duration must be positive");

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;

        bool reverted;
        uint256 loanID;
        uint256 id = c.clearRequest(0, repayDirect_, false); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            loanID = id;
            reverted = false;
        }

        assert(reverted || loanID == 0);
    }

    receive() external payable {}
}

