pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_) internal {
        vm.assume(amount_ > 0);
        vm.assume(loanToCollateral_ > 0);
        vm.assume(duration_ > 0);
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {} catch { return; }
        bool reverted;
        uint256 loanID;
        try c.clearRequest(0, repayDirect_, false) returns (uint256 id) {
            loanID = id;
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || loanID == 0);
    }

    function testFuzz_run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_) public {
        _run(amount_, interest_, loanToCollateral_, duration_, repayDirect_);
    }

    receive() external payable {}
}
